const input = $input.first().json;
const webhookBody = input.body || input;
const payload = webhookBody.payload || webhookBody;

// 1. Ignore outgoing messages from ourselves
if (payload.fromMe === true || payload._data?.key?.fromMe === true) {
  return [];
}

// 2. Extract message text
let rawText = '';
if (typeof payload.body === 'string') {
  rawText = payload.body;
} else if (payload.message && typeof payload.message.conversation === 'string') {
  rawText = payload.message.conversation;
} else if (payload._data?.message?.conversation && typeof payload._data.message.conversation === 'string') {
  rawText = payload._data.message.conversation;
} else if (payload._data?.message?.extendedTextMessage?.text) {
  rawText = payload._data.message.extendedTextMessage.text;
} else if (typeof payload.text === 'string') {
  rawText = payload.text;
}

if (!rawText || typeof rawText !== 'string' || !rawText.trim()) {
  return [];
}

// 3. Extract Customer Phone and ChatId
const remoteJid = payload._data?.key?.remoteJid || payload.from || '';
const remoteJidAlt = payload._data?.key?.remoteJidAlt || '';

let customerPhone = '';
if (remoteJidAlt && remoteJidAlt.includes('@')) {
  customerPhone = remoteJidAlt.split('@')[0].replace(/\D/g, '');
} else if (remoteJid && (remoteJid.includes('@s.whatsapp.net') || remoteJid.includes('@c.us'))) {
  customerPhone = remoteJid.split('@')[0].replace(/\D/g, '');
} else {
  customerPhone = remoteJid.replace(/\D/g, '');
}

const customerChatId = customerPhone ? (customerPhone + '@c.us') : (payload.from || remoteJid);

// 4. Extract Customer Name
let name = payload.pushName || payload._data?.pushName || 'عميل كريم';
name = name.replace(/^~+|~+$/g, '').trim();

return [{
  json: {
    customer_phone: customerPhone,
    customer_chatId: customerChatId,
    customer_name: name,
    raw_message: rawText,
    manager_chatId: '967730881873@c.us'
  }
}];

